@startuml
class Person {}
class Student extends Person {
  +name : string
  +email : string
}
class Tutor extends Person {
  +name : string
  +email : string
  +bankAccount : string
}
class Subject {}
class ExpertiseLevel {}
class Availability {
  +day : string
  +startTime : time
  +endTime : time
}
class TutoringOffer {
  +levelOfExpertise : ExpertiseLevel
  +hourlyPrice : float
}
class TutoringRequest {
  +level : ExpertiseLevel
  +targetDate : date
  +targetTime : time
}
class TutoringSession {
  +actualDate : date
  +actualTime : time
}
class Payment {
  +amount : float
  +method : string
}
class Award {
  +month : string
}

Student "0..*" -- "0..*" Tutor : may also be
Tutor "1" -- "*" TutoringOffer : offers
TutoringOffer "*" -- "1" Subject : in
Tutor "1" -- "*" Availability : specifies
Tutor "1" -- "*" TutoringOffer : provides
Student "1" -- "*" TutoringRequest : makes
Tutor "1" -- "*" TutoringRequest : receives
TutoringRequest "1" -- "0..1" TutoringSession : becomes
Student "1" -- "*" TutoringSession : attends
Tutor "1" -- "*" TutoringSession : attends
TutoringSession "1" -- "0..1" Payment : results in
Tutor "1" -- "*" Award : receives
Award "*" -- "1" Subject : for
@enduml

